import {discoveryPlan,nextDiscoveryRound} from './discovery.js?v=32';
import {parseContentBatch,videoMedia} from './content-json.js?v=32';
import {createCardWindow} from './card-window.js?v=32';
import {eligible,relevant,text} from './knowledge.js?v=32';
import {API_BASE} from './config.js';
const $=s=>document.querySelector(s);
const COVER_PLACEHOLDER='./assets/cover-placeholder.svg';
function coverFallback(img){if(img.dataset.coverFallback==='1'){img.hidden=true;return}img.dataset.coverFallback='1';img.hidden=false;img.removeAttribute('srcset');img.src=COVER_PLACEHOLDER;img.alt='默认知识封面'}
const storageRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const DISMISSED_KEY='ub-dismissed-videos-v1',DISMISS_DAYS=7*86400000;
function readDismissed(){const rows=storageRead(DISMISSED_KEY,[]);return new Map((Array.isArray(rows)?rows:[]).filter(row=>Array.isArray(row)&&typeof row[0]==='string'&&row[0].length<=120&&Number.isFinite(row[1])&&row[1]>Date.now()))}
let dismissedVideos=readDismissed();
function isDismissed(item){return item.kind!=='article'&&(dismissedVideos.get(item.bvid||item.id)||0)>Date.now()}
function dismissVideo(id,button){const item=library.get(id)||results.find(x=>x.id===id);if(!item||item.kind==='article')return;const key=item.bvid||id;dismissedVideos=new Map([...readDismissed(),...dismissedVideos].filter(([,until])=>until>Date.now()));dismissedVideos.set(key,Date.now()+DISMISS_DAYS);let stored=true;try{localStorage.setItem(DISMISSED_KEY,JSON.stringify([...dismissedVideos]))}catch{stored=false}
 results=results.filter(x=>!isDismissed(x));for(const entry of preloadQueue)entry.items=entry.items.filter(x=>!isDismissed(x));const card=button?.closest('.card');const hadFocus=card?.contains(document.activeElement),nextFocus=card?.nextElementSibling?.querySelector('button')||card?.previousElementSibling?.querySelector('button')||$('#more');if(card){cardWindow.remove(card);exposure.unobserve(card);card.remove();renderedIds=renderedIds.filter(value=>value!==id)}render();if(hadFocus)nextFocus?.focus({preventScroll:true});toast(stored?'已标记看过 · 7天内不再推荐':'当前页面已隐藏；浏览器未能保存7天屏蔽记录')}
window.addEventListener('storage',event=>{if(event.key===DISMISSED_KEY){dismissedVideos=readDismissed();for(const entry of preloadQueue)entry.items=entry.items.filter(x=>!isDismissed(x));if(view==='explore')render()}});
let contentType=storageRead('ub-content-type','all');if(!['all','article','video'].includes(contentType))contentType='all';
const stored=storageRead('ub-bili-library',[]);const library=new Map((Array.isArray(stored)?stored:[]).filter(x=>x&&typeof x.id==='string').map(x=>[x.id,x]));
const saved=new Set(storageRead('ub-saved',[]));let history=storageRead('ub-history',[]),questions=storageRead('ub-questions',[]);
if(!Array.isArray(history))history=[];if(!Array.isArray(questions))questions=[];
let aiSession=null,discoveryRound=0;const rejectedForFeed=new Set();let latestBatch=null;let metadataController=null;let liveQuery='',lastError='',renderedIds=[],emptyPages=0,feedPaused=false;let indexed=[],results=[],view='explore',topic='全部',batch=0,deadline=null,active=null,requestId=0,searchController=null,hasMore=false,livePage=1,loading=false;
const liveAvailable=Boolean(API_BASE)||!location.hostname.endsWith('github.io');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seenEntries=storageRead('ub-seen-v1',[]);const seen=new Map((Array.isArray(seenEntries)?seenEntries:[]).filter(x=>Array.isArray(x)&&typeof x[0]==='string'&&Date.now()-Number(x[1])<7*86400000));let seenWrite=0;
function markSeen(id){seen.delete(id);seen.set(id,Date.now());while(seen.size>700)seen.delete(seen.keys().next().value);if(!seenWrite)seenWrite=setTimeout(()=>{seenWrite=0;try{localStorage.setItem('ub-seen-v1',JSON.stringify([...seen]))}catch{}},250)}
const exposure=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting&&e.intersectionRatio>=0.35){const id=e.target.dataset.contentId;if(id){markSeen(id);const item=library.get(id);if(item?.url)markSeen(item.url);exposure.unobserve(e.target)}}},{threshold:0.35});
function persist(){try{localStorage.setItem('ub-saved',JSON.stringify([...saved]));localStorage.setItem('ub-history',JSON.stringify(history));localStorage.setItem('ub-questions',JSON.stringify(questions));const keep=new Set([...saved,...history,...indexed.map(x=>x.id)]);localStorage.setItem('ub-bili-library',JSON.stringify([...library.values()].filter(x=>keep.has(x.id)).slice(-300).map(({contentText,...metadata})=>metadata)))}catch{toast('当前浏览器无法保存记录')}}
function pruneLibrary(){if(library.size<=600)return;const keep=new Set([...saved,...history,...results.slice(-400).map(x=>x.id)]);for(const id of library.keys())if(!keep.has(id))library.delete(id)}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function duration(value){const total=Number(value)||0;return total>=3600?`${Math.floor(total/3600)}:${String(Math.floor(total/60)%60).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`:`${Math.floor(total/60)}:${String(total%60).padStart(2,'0')}`}
function setState(message){$('#searchStatus').textContent=message}
$('#searchMode').innerHTML='<option value="live">实时</option>';$('#searchMode').value='live';
const cardWindow=createCardWindow($('#cards'),{onMount:card=>{const b=card.querySelector('[data-save]');if(b)b.setAttribute('aria-pressed',String(saved.has(b.dataset.save)));card.removeAttribute('data-measured');scheduleLayout()}});
$('#cards').addEventListener('error',event=>{const img=event.target;if(img.tagName==='IMG')coverFallback(img)},true);
function render(){const query=$('#search').value.trim();let pool=view==='saved'?[...saved].map(id=>library.get(id)).filter(Boolean):view==='history'?history.map(id=>library.get(id)).filter(Boolean):results;
 const unfiltered=pool.length;pool=pool.filter(x=>(view!=='explore'||!isDismissed(x))&&(contentType==='all'||x.kind===contentType)&&(x.reviewed===true||x.filterEngine==='workflow'||eligible(x))&&(x.filterEngine==='workflow'||topic==='全部'||topic==='头版头条'&&x.news||x.topic===topic)&&($('#searchMode').value==='live'&&view==='explore'?true:relevant(x,query)));
 const list=pool;
 const grid=$('#cards');const ids=list.map(c=>c.id);const appendOnly=renderedIds.length<=ids.length&&renderedIds.every((id,i)=>id===ids[i]);if(!appendOnly){exposure.disconnect();cardWindow.reset();grid.replaceChildren();renderedIds=[]}const previousCount=renderedIds.length;const newItems=list.slice(previousCount);grid.insertAdjacentHTML('beforeend',newItems.map(c=>`<article class="card" data-content-id="${escape(c.id)}"><div class="card-body"><div class="art cover-art"><button class="content-open" data-open="${escape(c.id)}" aria-label="打开：${escape(c.title)}"><img decoding="async" src="${escape(c.cover||COVER_PLACEHOLDER)}" alt="${c.cover?'':'默认知识封面'}" ${c.cover?'':'data-cover-fallback="1"'} loading="lazy" referrerpolicy="no-referrer"><span class="play-icon" aria-hidden="true">${c.kind==='article'?'↗':'▷'}</span></button>${view==='explore'&&c.kind!=='article'?'<button class="dismiss-video" data-dismiss-video="'+escape(c.id)+'" type="button" aria-label="看过此视频，7天内不再推荐" title="看过，7天内不再推荐">看过</button>':''}<span class="format">${c.kind==='article'?'图文':duration(c.duration)}</span><button class="save" data-save="${escape(c.id)}" aria-label="收藏" aria-pressed="${saved.has(c.id)}">＋</button></div><button class="title-open" data-open="${escape(c.id)}"><h3>${escape(c.title)}</h3></button>${c.kind==='article'?'<p class="card-excerpt">'+escape(c.desc.slice(0,150))+'</p>':''}<div class="card-meta"><span class="card-source">${escape(c.source||'B站')} · ${c.news?escape(new Date(c.publishedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})):escape(c.author)}</span><a class="external" href="${escape(c.url||'https://www.bilibili.com/video/'+c.bvid+'/')}" target="_blank" rel="noopener noreferrer" aria-label="查看原文">↗</a></div></div></article>`).join(''));renderedIds=ids;for(let i=previousCount;i<grid.children.length;i++)if(grid.children[i].classList.contains('card')){cardWindow.observe(grid.children[i]);exposure.observe(grid.children[i])}
 $('#empty').hidden=list.length>0||loading;$('#cards').setAttribute('aria-busy',String(loading));$('#batchEnd').hidden=view!=='explore'||$('#searchMode').value!=='live';$('#more').disabled=loading||(!hasMore&&!lastError&&livePage>0);$('#more').textContent=loading?'加载中…':lastError?'重试':feedPaused?'继续查找':hasMore?'加载更多':results.length?'已到底':'加载内容';$('#more').hidden=!loading&&!lastError&&!hasMore&&results.length===0;scheduleLayout();
 $('#resultSummary').textContent=`${pool.length} 项结果；筛除 ${unfiltered-pool.length} 项；已加载 ${livePage} 页`;
 $('#savedCount').textContent=[...saved].filter(id=>library.has(id)).length;$('#sectionTitle').textContent=view==='saved'?'收藏':view==='history'?'足迹':'发现';
 $('#cards').querySelector('.question-list')?.remove();if(view==='history'&&questions.length){const section=document.createElement('section');section.className='question-list';const title=document.createElement('h3');title.textContent='问题';section.append(title);questions.slice(-5).reverse().forEach(q=>{const p=document.createElement('p');p.textContent=q.text;section.append(p)});$('#cards').append(section);$('#empty').hidden=true}
 document.querySelectorAll('[data-content-type]').forEach(button=>{const selected=button.dataset.contentType===contentType;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected))});
 $('#searchForm button[type=submit]').disabled=loading;
}
async function loadIndex(){indexed=[];results=[];$('#indexUpdated').textContent='实时公开来源';await searchLive()}
function classicQuery(page=1){const queries=['红楼梦 文学解读','陀思妥耶夫斯基 文学','鲁迅 文学解读','莎士比亚 文学','百年孤独 文学','西游记 文学','卡夫卡 文学','简爱 文学','围城 文学','悲惨世界 文学'];return queries[(page-1)%queries.length]}
function discoveryQuery(){return {'头版头条':'商业新闻','财经动态':'金融市场','商业':'企业商业','经典名著':classicQuery(livePage+1),'哲学与人文':'哲学 人文','心理与认知':'认知科学','社会与文化':'文化 艺术','科技与伦理':'人工智能 伦理','前沿科学':'前沿科学'}[topic]||'认知科学 科普'}
const preloadTarget=(()=>{try{const n=Number(localStorage.getItem('ub-preload-target')||1);const target=Math.min(6,Math.max(2,Number.isFinite(n)?n+1:2));localStorage.setItem('ub-preload-target',String(target));return target}catch{return 2}})();
let preloadQueue=[],preloadPending=null,preloadError=null,preloadPage=0,preloadMore=false,preloadEmpty=0;
function resetPreload(){preloadQueue=[];preloadPending=null;preloadError=null;preloadPage=0;preloadMore=false;preloadEmpty=0}
async function fetchFeedPage(page,id,explicit,ai){
 const plan=discoveryPlan(topic,discoveryRound,page),query=explicit||plan.query;
 const queued=preloadQueue.flatMap(b=>b.items.flatMap(x=>[x.id,x.url]));
 const exclusionPool=[...new Set([...results.flatMap(x=>[x.id,x.url]),...queued,...rejectedForFeed,...[...dismissedVideos].filter(([,until])=>until>Date.now()).map(([id])=>id)])];let exclusionBytes=0;const excludeIds=explicit?[]:exclusionPool.reverse().filter(id=>{if(typeof id!=='string'||exclusionBytes+id.length>55000)return false;exclusionBytes+=id.length;return true}).slice(0,700).reverse();
 const params={q:query,page:explicit?page:plan.page,order:'totalrank',source:contentType==='video'?'bilibili':contentType==='article'?'articles':'all',discovery:explicit?'0':'1',topic,seed:explicit?'':plan.seed+':'+page,excludeIds};
 const controller=new AbortController(),parent=searchController.signal,abort=()=>controller.abort();parent.addEventListener('abort',abort,{once:true});if(parent.aborted)abort();const timeout=setTimeout(abort,85000);
 try{const response=await fetch((API_BASE||'.')+'/api/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({params,ai}),signal:controller.signal});const raw=await response.json();if(id!==requestId)throw new DOMException('Stale feed','AbortError');if(!response.ok||raw.mode!=='live')throw Error(raw.error||'搜索暂不可用');const data=parseContentBatch(raw);if(data.stage!=='reviewed')throw Error('未完成筛选的内容不可展示');if(data.workflow?.status==='error')throw Error(data.warnings?.at(-1)||'AI 筛选失败，请重试');
 for(const d of data.decisions||[])if(d.keep===false&&typeof d.id==='string'){rejectedForFeed.delete(d.id);rejectedForFeed.add(d.id)}while(rejectedForFeed.size>400)rejectedForFeed.delete(rejectedForFeed.keys().next().value);
 const existing=new Set([...results,...preloadQueue.flatMap(b=>b.items)].map(x=>x.id));const items=data.items.filter(x=>!existing.has(x.id)&&!isDismissed(x)).map(x=>({...x,reviewed:true,filterEngine:data.filterEngine||'static'}));return {data,items,page,more:explicit?data.hasMore:true};
 }finally{clearTimeout(timeout);parent.removeEventListener('abort',abort)}
}
function queueNext(id,explicit){if(preloadPending)return preloadPending;if(id!==requestId||!preloadMore||preloadError)return Promise.resolve();const task=fetchFeedPage(preloadPage+1,id,explicit,aiSession).then(entry=>{if(id!==requestId)return;preloadPage=entry.page;preloadEmpty=entry.items.length?0:preloadEmpty+1;preloadMore=entry.more&&preloadEmpty<6;preloadQueue.push(entry)}).catch(error=>{if(id===requestId)preloadError=error}).finally(()=>{if(id===requestId&&preloadPending===task)preloadPending=null});preloadPending=task;return task}
async function fillPreload(id,explicit){while(id===requestId&&view==='explore'&&preloadMore&&!preloadError&&preloadQueue.length<preloadTarget)await queueNext(id,explicit)}
async function searchLive(next=false){
 if(loading&&next)return;const explicit=$('#search').value.trim();
 if(!next){searchController?.abort();requestId++;searchController=new AbortController();resetPreload();rejectedForFeed.clear();if(!explicit)discoveryRound=nextDiscoveryRound(topic);feedPaused=false;results=[];hasMore=false;livePage=0;emptyPages=0;latestBatch=null;liveQuery=explicit||discoveryPlan(topic,discoveryRound,1).query}
 const id=requestId;loading=true;lastError='';render();setState(next?'正在获取下一批…':explicit?'后端正在抓取并筛选…':'正在获取首批内容…');
 try{let entry;if(!next){entry=await fetchFeedPage(1,id,explicit,explicit?aiSession:{provider:'static'});if(id!==requestId)return;preloadPage=1;preloadMore=entry.more}else{if(!preloadQueue.length){preloadError=null;preloadMore=true;await queueNext(id,explicit)}if(id!==requestId)return;entry=preloadQueue.shift();if(!entry)throw preloadError||Error('暂无新内容，请重试')}
 if(id!==requestId)return;latestBatch=entry.data;entry.items.forEach(x=>library.set(x.id,x));const before=results.length;results=[...new Map([...results,...entry.items].map(x=>[x.id,x])).values()];livePage=entry.page;hasMore=preloadQueue.length>0||preloadMore;emptyPages=results.length>before?0:emptyPages+1;feedPaused=emptyPages>=6;setState(emptyPages>=6?'本轮暂未找到更多通过筛选的内容，可继续查找':entry.data.warnings?.length?entry.data.warnings.join('；'):'已发现 '+results.length+' 项内容');pruneLibrary();
 }catch(e){if(id!==requestId)return;lastError=e.name==='AbortError'?'请求超时，点击重试':e.message;setState(lastError);feedPaused=true}finally{if(id===requestId){loading=false;render();if(!feedPaused)void fillPreload(id,explicit)}}
}

function openContent(id){const item=library.get(id)||results.find(x=>x.id===id);if(!item)return;library.set(id,item);active=item;history=[id,...history.filter(x=>x!==id)].slice(0,100);persist();$('#viewerTitle').textContent=item.title;$('#viewerAuthor').textContent=`${item.source||'B站'} · ${item.author}`;$('#originalLink').href=item.url||`https://www.bilibili.com/video/${item.bvid}/`;$('#originalLink').textContent=item.kind==='article'?'原文 ↗':'原视频 ↗';const isArticle=item.kind==='article';$('#watchTab').hidden=isArticle;$('#readTab').hidden=!isArticle;$('#readTab').textContent='阅读';const cover=$('#readerCover');cover.hidden=!isArticle;delete cover.dataset.coverFallback;if(isArticle){$('.reader-label').textContent=item.contentText?'公开网页正文':'来源简介';if(!item.cover)cover.dataset.coverFallback='1';cover.src=item.cover||COVER_PLACEHOLDER;cover.alt=item.cover?'原文封面':'默认知识封面';$('#videoDescription').textContent=item.contentText||item.desc||'来源暂未提供可读取的正文。'}else{$('.reader-label').textContent='';$('#videoDescription').textContent='';cover.removeAttribute('src')}$('#parts').replaceChildren();(item.pages?.length?item.pages:[{page:1,part:'第 1 集'}]).forEach(p=>{const option=document.createElement('option');option.value=p.page;option.textContent=`${p.page}. ${p.part}`;$('#parts').append(option)});$('#parts').hidden=(item.pages?.length||1)<2;$('#viewer').showModal();setViewerTab(item.kind==='article'?'read':'watch');if(item.kind!=='article')loadPlayer(1);}
function applyVideoRatio(item){const media=videoMedia(item);$('#playerFrame').style.setProperty('--video-ratio',String(media.aspectRatio||16/9));$('#playerFrame').dataset.orientation=media.orientation}
async function resolveVideoRatio(item){metadataController?.abort();metadataController=new AbortController();const controller=metadataController;try{const r=await fetch(`${API_BASE||'.'}/api/video?bvid=${encodeURIComponent(item.bvid)}`,{signal:controller.signal});if(!r.ok)return;const d=await r.json();if(active?.id!==item.id||d.bvid!==item.bvid)return;item.media=d.media;item.dimension=null;applyVideoRatio(item)}catch{}}
function loadPlayer(page){if(!active)return;applyVideoRatio(active);if(videoMedia(active).orientation==='unknown')resolveVideoRatio(active);const player=document.createElement('iframe');const url=new URL('https://player.bilibili.com/player.html');url.search=new URLSearchParams({bvid:active.bvid,p:String(page),autoplay:'0',danmaku:'0',poster:'1'});player.src=url.href;player.title=active.title;player.allow='fullscreen; picture-in-picture; encrypted-media';player.allowFullscreen=true;player.referrerPolicy='strict-origin-when-cross-origin';$('#playerFrame').replaceChildren(player);$('#playerHint').hidden=false;player.addEventListener('load',()=>{$('#playerHint').textContent='播放由 B站提供；如受限，可查看原视频。'},{once:true});}
function setViewerTab(tab){const reading=active?.kind==='article'&&tab==='read';$('#watchPane').hidden=reading;$('#readPane').hidden=!reading;$('#watchTab').setAttribute('aria-selected',String(!reading));$('#readTab').setAttribute('aria-selected',String(reading));}
$('#viewer').addEventListener('close',()=>{metadataController?.abort();$('#playerFrame').replaceChildren();active=null});$('#readerCover').onerror=()=>coverFallback($('#readerCover'));$('#exportJson').onclick=()=>{if(!latestBatch){toast('暂无可导出的结果');return}const blob=new Blob([JSON.stringify(latestBatch,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`unbrainrot-${latestBatch.stage}-${latestBatch.batchId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#viewerClose').onclick=()=>$('#viewer').close();$('#watchTab').onclick=()=>setViewerTab('watch');$('#readTab').onclick=()=>setViewerTab('read');$('#parts').onchange=()=>loadPlayer(Number($('#parts').value));
$('#searchForm').addEventListener('submit',e=>{e.preventDefault();batch=0;if($('#searchMode').value==='live'&&view==='explore')searchLive();else{results=indexed;hasMore=false;render()}});
$('#search').addEventListener('input',()=>{searchController?.abort();requestId++;resetPreload();loading=false;hasMore=false;batch=0;if($('#searchMode').value==='index'){results=indexed}else{results=[];setState('B站实时 · 输入后搜索')}render()});
$('#searchMode').onchange=()=>{searchController?.abort();requestId++;resetPreload();loading=false;batch=0;hasMore=false;results=indexed;lastError='';feedPaused=false;setState($('#searchMode').value==='live'?'搜索 B站…':`B站目录 · ${indexed.length} 项`);render();if($('#searchMode').value==='live')searchLive()};
function switchView(next){searchController?.abort();requestId++;resetPreload();loading=false;view=next;topic='全部';batch=0;hasMore=false;results=indexed;$('#search').value='';$('#searchMode').value=next==='explore'&&liveAvailable?'live':'index';lastError='';feedPaused=false;setState(next==='explore'?`B站目录 · ${indexed.length} 项`:'');document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===view);if(n.dataset.view===view)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});render();if(next==='explore'&&liveAvailable)searchLive()}
$('#contentType').addEventListener('click',event=>{const button=event.target.closest('[data-content-type]');if(!button||button.dataset.contentType===contentType)return;contentType=button.dataset.contentType;try{localStorage.setItem('ub-content-type',JSON.stringify(contentType))}catch{}if(view==='explore')searchLive();else render()});
$('#refreshFeed').onclick=()=>{if(view!=='explore')switchView('explore');else{if($('#search').value.trim())$('#search').value='';searchLive()}};$('#reset').onclick=()=>switchView('explore');$('#more').onclick=()=>{feedPaused=false;searchLive(livePage>0)};
let layoutFrame=0,lastWidth=0,fullLayout=false;
function scheduleLayout(all=false){fullLayout ||=all;if(!layoutFrame)layoutFrame=requestAnimationFrame(()=>{layoutFrame=0;layoutMasonry(fullLayout);fullLayout=false;maybeLoadMore()})}
function layoutMasonry(all=false){const grid=$('#cards'),style=getComputedStyle(grid);if(style.display!=='grid')return;const unit=parseFloat(style.gridAutoRows)||8,gap=parseFloat(style.rowGap)||20;const cards=[...grid.querySelectorAll('.card:not([data-virtual="placeholder"])')].filter(c=>all||!c.dataset.measured);const spans=cards.map(c=>Math.ceil((c.querySelector('.card-body').getBoundingClientRect().height+gap)/(unit+gap)));cards.forEach((c,i)=>{c.style.gridRowEnd='span '+spans[i];c.dataset.measured='1'})}
const resize=new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(Math.abs(width-lastWidth)>1){lastWidth=width;scheduleLayout(true)}});resize.observe($('#cards'));document.fonts.ready.then(()=>scheduleLayout(true));
function maybeLoadMore(){if(view==='explore'&&$('#searchMode').value==='live'&&!loading&&!feedPaused&&hasMore&&!$('#viewer').open&&$('#batchEnd').getBoundingClientRect().top<innerHeight+250)searchLive(true)}
const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))maybeLoadMore()},{rootMargin:'250px 0px'});observer.observe($('#batchEnd'));

 document.addEventListener('click',e=>{const dismiss=e.target.closest('[data-dismiss-video]');if(dismiss){e.preventDefault();dismissVideo(dismiss.dataset.dismissVideo,dismiss);return}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;const item=library.get(id)||results.find(x=>x.id===id);if(item)library.set(id,item);saved.has(id)?saved.delete(id):saved.add(id);persist();if(view==='saved')render();else save.setAttribute('aria-pressed',String(saved.has(id)));return}const open=e.target.closest('[data-open]');if(open){e.preventDefault();openContent(open.dataset.open);return}const nav=e.target.closest('[data-view]');if(nav)switchView(nav.dataset.view)});
function updateTimer(){const b=$('#focus');b.classList.toggle('running',deadline!==null);if(deadline){const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));b.querySelector('span').textContent=duration(remaining);if(!remaining){deadline=null;if($('#viewer').open)$('#viewer').close();$('#reflection').showModal();updateTimer()}}else b.querySelector('span').textContent='20:00';b.setAttribute('aria-label',deadline?'结束本次探索':'开始 20 分钟探索')}
$('#focus').onclick=()=>{if(deadline){deadline=null;$('#reflection').showModal()}else{deadline=Date.now()+1200000;toast('计时开始 · 关闭页面后不再提醒')}updateTimer()};setInterval(updateTimer,1000);
$('#saveQuestion').onclick=e=>{const value=$('#question').value.trim();if(!value){e.preventDefault();$('#question').focus();return}questions.push({text:value,date:new Date().toISOString()});persist();$('#question').value='';toast('已保存到足迹');if(view==='history')render()};$('#about').onclick=()=>$('#info').showModal();

function aiFields(){const custom=$('#aiProvider').value==='dify';for(const name of ['aiKey','aiEndpoint','aiInputVariable','aiOutputVariable']){$('#'+name).disabled=!custom;$('#'+name+'Group').hidden=!custom}}
function updateAIButton(){$('#aiSettings').classList.toggle('active',aiSession?.provider==='dify');$('#aiSettings').title=aiSession?.provider==='dify'?'当前页面已配置 Dify 抓取筛选':'AI 配置'}
$('#aiSettings').onclick=()=>{$('#aiProvider').value=aiSession?.provider||'server';$('#aiKey').value='';$('#aiKey').placeholder=aiSession?.key?'当前会话已配置；留空保留':'Dify 应用 API Key';$('#aiEndpoint').value=aiSession?.endpoint||'https://api.dify.ai/v1';$('#aiInputVariable').value=aiSession?.inputVariable||'payload';$('#aiOutputVariable').value=aiSession?.outputVariable||'result';aiFields();$('#aiConfig').showModal()};$('#aiProvider').onchange=()=>{$('#aiKey').value='';aiFields()};$('#aiConfig').addEventListener('close',()=>{$('#aiKey').value=''});$('#aiCancel').onclick=()=>$('#aiConfig').close();
$('#aiForm').onsubmit=e=>{e.preventDefault();const provider=$('#aiProvider').value;if(provider==='dify'){const endpoint=$('#aiEndpoint').value.trim();const key=$('#aiKey').value.trim()||(aiSession?.provider==='dify'&&endpoint===aiSession.endpoint?aiSession.key:'');if(!key){$('#aiMessage').textContent='请填写已发布 Workflow 的 Dify 应用 Key';$('#aiKey').focus();return}aiSession={provider,key,endpoint,inputVariable:$('#aiInputVariable').value.trim()||'payload',outputVariable:$('#aiOutputVariable').value.trim()||'result'}}else aiSession=provider==='static'?{provider:'static'}:null;$('#aiKey').value='';$('#aiMessage').textContent='';$('#aiConfig').close();updateAIButton();toast('已应用到后端抓取筛选');if(view!=='explore')switchView('explore');else searchLive()};
$('#aiClear').onclick=()=>{aiSession=null;$('#aiKey').value='';$('#aiMessage').textContent='';$('#aiConfig').close();updateAIButton();toast('已清除当前页面配置');if(view==='explore')searchLive()};
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});loadIndex();
